func (v DataValue) Equal(o attr.Value) bool {
	other, ok := o.(DataValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.AssignedBy.Equal(other.AssignedBy) {
		return false
	}

	if !v.Assignee.Equal(other.Assignee) {
		return false
	}

	if !v.Content.Equal(other.Content) {
		return false
	}

	if !v.Date.Equal(other.Date) {
		return false
	}

	if !v.DateAssigned.Equal(other.DateAssigned) {
		return false
	}

	if !v.DateResolved.Equal(other.DateResolved) {
		return false
	}

	if !v.DateUpdated.Equal(other.DateUpdated) {
		return false
	}

	if !v.GroupAssignee.Equal(other.GroupAssignee) {
		return false
	}

	if !v.Id.Equal(other.Id) {
		return false
	}

	if !v.Links.Equal(other.Links) {
		return false
	}

	if !v.ParentChannel.Equal(other.ParentChannel) {
		return false
	}

	if !v.ParentMessage.Equal(other.ParentMessage) {
		return false
	}

	if !v.PostData.Equal(other.PostData) {
		return false
	}

	if !v.RepliesCount.Equal(other.RepliesCount) {
		return false
	}

	if !v.Resolved.Equal(other.Resolved) {
		return false
	}

	if !v.ResolvedBy.Equal(other.ResolvedBy) {
		return false
	}

	if !v.TriagedAction.Equal(other.TriagedAction) {
		return false
	}

	if !v.TriagedObjectId.Equal(other.TriagedObjectId) {
		return false
	}

	if !v.TriagedObjectType.Equal(other.TriagedObjectType) {
		return false
	}

	if !v.DataType.Equal(other.DataType) {
		return false
	}

	if !v.UserId.Equal(other.UserId) {
		return false
	}

	return true
}

